import { inflateSync, strFromU8 } from "fflate";

export interface RawBookJson {
  abbrev: string;
  name: string;
  chapters: string[][];
}

const COMPRESSED_BIBLE_B64 = "";

let cachedBooks: RawBookJson[] | null = null;

export function getRawBibleArcBooks(): RawBookJson[] {
  if (cachedBooks) return cachedBooks;
  try {
    const binStr = typeof atob === "function"
      ? atob(COMPRESSED_BIBLE_B64)
      : Buffer.from(COMPRESSED_BIBLE_B64, "base64").toString("binary");
    const len = binStr.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binStr.charCodeAt(i);
    }
    const inflated = inflateSync(bytes);
    const jsonStr = strFromU8(inflated);
    cachedBooks = JSON.parse(jsonStr) as RawBookJson[];
    return cachedBooks;
  } catch (err) {
    console.error("[BibliaARC] Erro ao descompactar base bíblica:", err);
    return [];
  }
}
